args.command:
cd /tau/self; node - /tau/in/list.txt <<'EOF'
import { readFileSync } from 'node:fs'
import { addNote } from '@api/notes'

const ids: number[] = []
for (const line of readFileSync(process.argv[2] ?? '', 'utf8').split('\n').filter(Boolean)) {
  const [text = '', tags = ''] = line.split('#')
  const note = await addNote(text.trim(), tags.split(',').map(tag => tag.trim()).filter(Boolean))
  ids.push(note.id)
}
console.log(JSON.stringify(ids))
EOF
